+use Neos\Diff\Renderer\AbstractRenderer;
+
+/**
+ * Array renderer for HTML based diffs
+ */
+class HtmlArrayRenderer extends AbstractRenderer
+{
+    /**
+     * @var array Array of the default options that apply to this renderer.
+     */
+    protected $defaultOptions = array(
+        'tabSize' => 4
+    );
+
+    /**
+     * Render and return an array structure suitable for generating HTML
+     * based differences. Generally called by subclasses that generate a
+     * HTML based diff and return an array of the changes to show in the diff.
+     *
+     * @return array An array of the generated chances, suitable for presentation in HTML.
+     */
+    public function render()
+    {
+        // As we'll be modifying a & b to include our change markers,
+        // we need to get the contents and store them here. That way
+        // we're not going to destroy the original data
+        $a = $this->diff->getA();
+        $b = $this->diff->getB();
+
+        $changes = array();
+        $opCodes = $this->diff->getGroupedOpcodes();
+        foreach ($opCodes as $group) {
+            $blocks = array();
+            $lastTag = null;
+            $lastBlock = 0;
+            foreach ($group as $code) {
+                list($tag, $i1, $i2, $j1, $j2) = $code;
+
+                if ($tag == 'replace' && $i2 - $i1 == $j2 - $j1) {
