+    printf("%03lu=%9.3g,%9.3g,%7d\t", i, h[i].sum_gradients, h[i].sum_hessians, h[i].cnt);
+    total += h[i].cnt;
+    if ((i & 3) == 3)
+        printf("\n");
+  }
+  printf("\nTotal examples: %lu\n", total);
+}
