+			MAXTASKSETS,
+			MAXTASKS
+		)
+	);
+
+	for (auto &task_set: rows) {
+		m_task_sets[task_set.id].push_back(task_set.taskid);
+		LogTasksDetail("[LoadTaskSets] Adding task_id [{}] to task_set [{}]", task_set.taskid, task_set.id);
+	}
+
+	return true;
+}
