+template<typename T>
+std::string clGetKernelName(std::string name) {
+
+	std::stringstream ss;
+	ss<<name;
+
+	if ( typeid(T) == typeid(float) ) {
+		ss<<"Float";
+	}
+	if ( typeid(T) == typeid(double) ) {
+		ss<<"Double";
+	}
+	if ( typeid(T) == typeid(char) ) {
+		ss<<"Char";
+	}
+	if ( typeid(T) == typeid(int) ) {
+		ss<<"Int";
+	}
+
+	return ss.str();
+}
