+            {
+                VLatest.UpsertSearchParamStatus.PopulateCommand(sqlCommandWrapper, _updateSearchParamRegistryTvpGenerator.Generate(statuses.ToList()));
+
+                await sqlCommandWrapper.ExecuteScalarAsync(CancellationToken.None);

