+CommandChatCreate::CommandChatCreate(MegaClient *client, bool group, userpriv_vector *upl)
+{
+    this->client = client;
+    this->chatPeers = upl;
+
+    cmd("mcc");
+    arg("g", (group) ? 1 : 0);
+
+    beginarray("u");
+
+    userpriv_vector::iterator itupl;
+    for (itupl = upl->begin(); itupl != upl->end(); itupl++)
+    {
+        beginobject();
+
+        handle uh = itupl->first;
+        char uid[12];
+        Base64::btoa((byte*)&uh, sizeof uh, uid);
+        uid[11] = 0;
+
+        privilege_t priv = itupl->second;
+
+        arg("u", uid);
+        arg("p", priv);
+
+        endobject();
+    }
+
+    endarray();
+
+    tag = client->reqtag;
+}
+
+void CommandChatCreate::procresult()
+{
+    if (client->json.isnumeric())
+    {
+        client->app->chatcreate_result(NULL, (error)client->json.getint());
+    }
+    else
+    {
+        string url;
+        handle chatid = UNDEF;
+        int shard = -1;
+        bool group = false;
+
+        for (;;)
+        {
+            switch (client->json.getnameid())
+            {
+                case MAKENAMEID3('u','r','l'):
+                    client->json.storeobject(&url);
+                    break;
+
+                case MAKENAMEID2('i','d'):
+                    chatid = client->json.gethandle(MegaClient::CHATHANDLE);
+                    break;
+
+                case MAKENAMEID2('c','s'):
+                    shard = client->json.getint();
+                    break;
+
+                case 'g':
+                    group = client->json.getint();
+                    break;
+
+                case EOO:
+                    if (chatid != UNDEF && !url.empty() && shard != -1)
+                    {
+                        TextChat *chat = new TextChat;
+                        chat->id = chatid;
+                        chat->priv = PRIV_OPERATOR;
+                        chat->url = url;
+                        chat->shard = shard;
+                        chat->userpriv = this->chatPeers;
+                        chat->group = group;
+
+                        client->app->chatcreate_result(chat, API_OK);
+                        delete chat;
+                    }
+                    else
+                    {
+                        client->app->chatcreate_result(NULL, API_EINTERNAL);
+                    }
+                    return;
+
+                default:
+                    if (!client->json.storeobject())
+                    {
+                        client->app->chatcreate_result(NULL, API_EINTERNAL);
+                    }
+            }
+        }
+    }
